console.log('⏳ Cell 1: generating data...');

const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const regions = ['Jakarta','Surabaya','Bandung','Medan','Semarang','Makassar','Palembang','Denpasar'];

let seed = 42;
const rng = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };

const rows = [];
let id = 1;
for (let mi = 0; mi < months.length; mi++) {
  for (const region of regions) {
    if (id > 93) break;
    const revenue = Math.round(50000 + rng() * 200000);
    const expenses = Math.round(30000 + rng() * 120000);
    const profit = revenue - expenses;
    const margin = Math.round((profit / revenue) * 10000) / 100;
    const date = `2026-${String(mi + 1).padStart(2, '0')}-01`;
    rows.push({ id: id++, month: months[mi], date, region, revenue, expenses, profit, margin });
  }
}

console.log(`✓ Cell 1: ${rows.length} rows ready`);
return { rows };

